package daemon

// The app-server protocol is generated by the installed Codex CLI with
// `codex app-server generate-ts`. Unlike exec, it supports steering and
// reports the effective thread configuration and structured item lifecycle.
import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"sync"
	"time"

	agent "github.com/blerglab/blerg-ai/runner/internal/agent"
)

type codexQuestionStatus struct{ turn, status string }

type codexRPC struct {
	questionStatus *codexQuestionStatus
	childProof     *codexChildProof
	ID             json.RawMessage `json:"id"`
	Method         string          `json:"method"`
	Params         json.RawMessage `json:"params"`
	Result         json.RawMessage `json:"result"`
	Error          json.RawMessage `json:"error"`
}
type codexApp struct {
	d                   *codexDriver
	ctx                 context.Context
	in                  io.WriteCloser
	mu                  sync.Mutex
	writeGate           chan struct{} // one native stdin writer, independent of lifecycle state
	next                int
	pending             map[int]chan codexRPC
	events              chan struct{}
	backlog             []codexRPC
	backlogBytes        int
	failure             string
	interruptRequested  bool
	capRefreshing       bool
	capRefreshAgain     bool
	starting            bool
	dynamicCalls        map[string]codexDynamicCall
	pendingQuestions    map[string]bool
	blockingQuestions   map[string]int
	childTurns          map[string]string
	pendingChildren     map[string]*codexPendingChild
	pendingChildBytes   int
	interruptedChildren map[string]string
	done                chan struct{}
	turn                string
}

func (a *codexApp) write(v any) error {
	ctx := a.ctx
	if ctx == nil {
		ctx = context.Background()
	}
	return a.writeContext(ctx, v)
}

// A full native stdin pipe must never hold the lifecycle mutex or bypass an
// RPC deadline. Only the gate owner starts a writer; cancellation closes the
// pipe and stops the native process, unblocking that one write and forcing a
// same-thread runtime restart rather than leaving a half-written protocol.
func (a *codexApp) writeContext(parent context.Context, v any) error {
	ctx, cancel := context.WithTimeout(parent, 5*time.Second)
	defer cancel()
	body, err := json.Marshal(v)
	if err != nil {
		return err
	}
	if len(body) > 8<<20 {
		return errors.New("codex request exceeds the native safety limit")
	}
	body = append(body, '\n')
	a.mu.Lock()
	if a.writeGate == nil {
		a.writeGate = make(chan struct{}, 1)
	}
	gate := a.writeGate
	a.mu.Unlock()
	var appDone <-chan struct{}
	if a.ctx != nil {
		appDone = a.ctx.Done()
	}
	select {
	case gate <- struct{}{}:
	case <-ctx.Done():
		return ctx.Err()
	case <-appDone:
		return a.ctx.Err()
	}
	if err = ctx.Err(); err != nil {
		<-gate
		return err
	}
	if a.ctx != nil && a.ctx.Err() != nil {
		<-gate
		return a.ctx.Err()
	}
	finished := make(chan error, 1)
	go func() {
		defer func() { <-gate }()
		n, writeErr := a.in.Write(body)
		if writeErr == nil && n != len(body) {
			writeErr = io.ErrShortWrite
		}
		finished <- writeErr
	}()
	select {
	case err = <-finished:
		return err
	case <-ctx.Done():
		err = ctx.Err()
	case <-appDone:
		err = a.ctx.Err()
	}
	_ = a.in.Close()
	if a.d != nil {
		a.stop()
	}
	return err
}

func (a *codexApp) call(method string, params any) (json.RawMessage, error) {
	return a.callContext(a.ctx, method, params)
}
func (a *codexApp) callContext(ctx context.Context, method string, params any) (json.RawMessage, error) {
	a.mu.Lock()
	a.next++
	id := a.next
	ch := make(chan codexRPC, 1)
	a.pending[id] = ch
	a.mu.Unlock()
	defer func() { a.mu.Lock(); delete(a.pending, id); a.mu.Unlock() }()
	if err := a.writeContext(ctx, map[string]any{"id": id, "method": method, "params": params}); err != nil {
		return nil, err
	}
	timer := time.NewTimer(30 * time.Second)
	defer timer.Stop()
	select {
	case r := <-ch:
		if len(r.Error) > 0 && string(r.Error) != "null" {
			var rejection struct {
				Code    int
				Message string
			}
			_ = json.Unmarshal(r.Error, &rejection)
			return nil, codexRPCRejected{method: method, noActiveTurn: method == "turn/steer" && rejection.Code == -32600 && rejection.Message == "no active turn to steer"}
		}
		return r.Result, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-a.ctx.Done():
		return nil, a.ctx.Err()
	case <-a.done:
		return nil, fmt.Errorf("codex app-server disconnected")
	case <-timer.C:
		return nil, fmt.Errorf("%s timed out", method)
	}
}
func (a *codexApp) read(r io.Reader) {
	defer close(a.done)
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 65536), 8<<20)
	for sc.Scan() {
		var v codexRPC
		if json.Unmarshal(sc.Bytes(), &v) != nil {
			continue
		}
		if len(v.ID) > 0 && v.Method == "" {
			var id int
			if json.Unmarshal(v.ID, &id) == nil {
				a.mu.Lock()
				ch := a.pending[id]
				a.mu.Unlock()
				if ch != nil {
					// Exactly one reply belongs to a call. A duplicated native response
					// must not block this reader after the original caller has returned.
					select {
					case ch <- v:
					default:
					}
				}
			}
			continue
		}
		a.mu.Lock()
		if len(a.backlog) >= 4096 || a.backlogBytes+len(v.Params) > 64<<20 {
			a.failure = "Codex event backlog exceeded its safety limit; resume the saved thread"
			a.mu.Unlock()
			return
		}
		a.backlogBytes += len(v.Params)
		a.backlog = append(a.backlog, v)
		a.mu.Unlock()
		select {
		case a.events <- struct{}{}:
		default:
		}
	}
}
func (a *codexApp) interrupt() {
	root := a.threadID()
	type target struct{ thread, turn string }
	a.mu.Lock()
	targets := []target{}
	if a.turn != "" {
		targets = append(targets, target{root, a.turn})
	}
	for thread, turn := range a.childTurns {
		targets = append(targets, target{thread, turn})
	}
	if len(targets) == 0 && !a.starting && len(a.dynamicCalls) == 0 {
		a.mu.Unlock()
		return
	}
	// A stop directed at child-only work must not interrupt a future root turn.
	a.interruptRequested = a.turn != "" || a.starting
	if a.interruptedChildren == nil {
		a.interruptedChildren = map[string]string{}
	}
	for thread, turn := range a.childTurns {
		a.interruptedChildren[thread] = turn
	}
	a.mu.Unlock()
	a.cancelDynamic("", "")
	if len(targets) == 0 {
		return
	}
	go func() {
		for _, t := range targets {
			_, err := a.call("turn/interrupt", map[string]any{"threadId": t.thread, "turnId": t.turn})
			if err != nil && a.ctx.Err() == nil {
				var rejected codexRPCRejected
				if !errors.As(err, &rejected) {
					a.stop()
				}
				a.d.emit("error", agent.ErrorPayload{Message: err.Error(), Retryable: true})
			}
			if a.ctx.Err() != nil {
				return
			}
		}
	}()
}

func (d *codexDriver) runApp(ctx context.Context) {
	appCtx, cancelApp := context.WithCancel(ctx)
	defer cancelApp()
	bin := resolveEngineBinary("codex", d.prefix.enabled())
	args := d.launchArgs()
	if d.prefix.enabled() && d.CodexHome != "" {
		args = append([]string{"CODEX_HOME=" + d.CodexHome, bin}, args...)
		bin = "env"
	}
	cmd := d.prefix.command(ctx, d.workDir, bin, args...)
	cmd.Env = d.launchEnv()
	in, err := cmd.StdinPipe()
	if err != nil {
		d.emit("error", agent.ErrorPayload{Message: "Codex input pipe failed", Retryable: true})
		return
	}
	out, err := cmd.StdoutPipe()
	if err != nil {
		d.emit("error", agent.ErrorPayload{Message: "Codex output pipe failed", Retryable: true})
		return
	}
	// stderr can contain credentials from third-party MCP processes. Only fixed
	// diagnostics for recognized native login failures may reach the session.
	cmd.Stderr = &codexAuthDiagnostic{emit: d.emit}
	if err = cmd.Start(); err != nil {
		d.emit("error", agent.ErrorPayload{Message: "Codex app-server could not start: " + err.Error(), Retryable: true})
		return
	}
	a := &codexApp{d: d, ctx: appCtx, in: in, pending: map[int]chan codexRPC{}, events: make(chan struct{}, 1), done: make(chan struct{})}
	d.mu.Lock()
	d.cmd = cmd
	a.interruptRequested = d.interruptNext
	d.interruptNext = false
	d.app = a
	d.mu.Unlock()
	defer func() {
		_ = in.Close()
		_ = cmd.Process.Kill()
		_ = cmd.Wait()
		d.prefix.clearTurnPID()
		d.mu.Lock()
		wasActive := d.activeTurn
		turnModel := d.model
		d.cmd = nil
		d.app = nil
		d.activeTurn = false
		d.mu.Unlock()
		if ctx.Err() == nil {
			d.stopChildren()
		}
		if wasActive && ctx.Err() == nil {
			d.emit("turn_done", agent.TurnDonePayload{StopReason: "interrupted", Model: turnModel})
			d.emit("status_changed", agent.StatusPayload{Status: "idle", Reason: "engine_restart"})
		}
	}()
	if d.onEngine != nil {
		d.onEngine(cmd.Process.Pid, true)
		defer d.onEngine(cmd.Process.Pid, false)
	}
	go a.read(out)
	if _, err = a.call("initialize", map[string]any{"clientInfo": map[string]string{"name": "blerg_runner", "title": "Blerg", "version": "1"}, "capabilities": map[string]bool{"experimentalApi": true}}); err != nil {
		d.emit("error", agent.ErrorPayload{Message: "Codex initialization failed", Retryable: true})
		return
	}
	_ = a.writeContext(appCtx, map[string]any{"method": "initialized"})
	if err := a.loginManagedCredential(appCtx); err != nil {
		d.emit("error", agent.ErrorPayload{Message: "Codex managed login is unavailable. Reconnect the credential in Settings and retry.", Retryable: true, Code: agent.ErrorCodeAPI})
		return
	}
	a.loadModelCatalog()
	d.mu.Lock()
	d.effort = d.reconcileEffortLocked(d.model, d.effort)
	model, effort, thread := d.model, d.effort, d.threadID
	d.mu.Unlock()
	params := map[string]any{"cwd": d.runtimeWorkDir(), "approvalPolicy": "never", "sandbox": "danger-full-access"}
	config := map[string]any{}
	if !d.codexToolsRestricted() {
		for k, v := range d.RuntimeConfig {
			config[k] = v
		}
	}
	if d.RestrictedRuntime != nil {
		if err := codexDisableAmbientMCP(a, d.runtimeWorkDir(), config); err != nil {
			d.emit("error", agent.ErrorPayload{Message: "Codex MCP isolation could not be verified", Retryable: false})
			return
		}
	}
	instructions := d.DeveloperInstructions
	if instructions == "" {
		instructions = ccSystemPromptFor("")
	}
	if d.codexToolsRestricted() {
		params["sandbox"] = "read-only"
		instructions = "This is a restricted Blerg session. Only the supplied workspace file tools and explicitly granted MCP tools are available."
	} else {
		instructions += "\n\n" + codexQuestionHandoffInstructions
	}
	params["developerInstructions"] = instructions
	if model != "" {
		params["model"] = model
	}
	if effort != "" {
		config["model_reasoning_effort"] = effort
	}
	if len(config) > 0 {
		params["config"] = config
	}
	if d.RestrictedRuntime != nil {
		params["dynamicTools"] = d.RestrictedRuntime.Specs()
	}
	method := "thread/start"
	if thread != "" {
		method = "thread/resume"
		params["threadId"] = thread
		params["excludeTurns"] = true
		delete(params, "dynamicTools")
	}
	raw, err := a.call(method, params)
	if err != nil {
		d.emit("error", agent.ErrorPayload{Message: "Codex thread could not be loaded", Retryable: true})
		return
	}
	var response struct {
		Thread struct {
			ID string `json:"id"`
		} `json:"thread"`
		Model  string `json:"model"`
		Effort string `json:"reasoningEffort"`
	}
	if json.Unmarshal(raw, &response) != nil || !validCodexThreadID(response.Thread.ID) || (thread != "" && response.Thread.ID != thread) {
		d.emit("error", agent.ErrorPayload{Message: "Codex returned an unexpected thread identity", Retryable: true})
		return
	}
	if response.Effort == "" {
		response.Effort = a.defaultEffort(response.Model)
	}
	d.mu.Lock()
	d.threadID = response.Thread.ID
	if d.model == model {
		d.model = response.Model
	}
	if d.effort == effort {
		d.effort = response.Effort
	}
	thread = d.threadID
	d.mu.Unlock()
	if d.onThreadID != nil {
		d.onThreadID(thread)
	}
	d.mu.Lock()
	effective := agent.ModelChangedPayload{Model: d.model, Effort: d.effort, Source: "start"}
	d.mu.Unlock()
	d.emit("model_changed", effective)
	if d.codexToolsRestricted() {
		d.caps.emit(d.emitter, d.RestrictedRuntime.capabilities(response.Model))
	} else {
		a.requestCapabilities()
		go a.backgroundTerminals()
		go a.discoverOwnedChildren()
	}
	var active, turnModel string
	var usage agent.Usage
	var usageBase agent.Usage
	usageSeen := false
	var retryDeadline <-chan time.Time
	for {
		input := (<-chan queuedMsg)(d.queue)
		retrying := false
		d.mu.Lock()
		retry := d.retryInput
		d.mu.Unlock()
		if a.completionQueued(thread, active) || (retry != nil && active != "") {
			// Apply an already-queued completion before deciding start versus
			// steer. Ordinary streamed output must not starve mid-turn input.
			input = nil
		} else if retry != nil {
			first := make(chan queuedMsg, 1)
			first <- *retry
			input = first
			retrying = true
		}
		select {
		case <-retryDeadline:
			// The rejection proved this input was not accepted. Preserve it across
			// reconnection if the matching completion notification never arrives.
			return
		case <-ctx.Done():
			return
		case <-a.done:
			if ctx.Err() == nil {
				a.mu.Lock()
				failure := a.failure
				a.mu.Unlock()
				if failure == "" {
					failure = "Codex app-server disconnected; restart the session to resume its saved thread"
				}
				d.emit("error", agent.ErrorPayload{Message: failure, Retryable: true})
			}
			return
		case msg := <-input:
			if retrying {
				d.mu.Lock()
				d.retryInput = nil
				d.mu.Unlock()
				retryDeadline = nil
			}
			d.mu.Lock()
			superseded := msg.adoptionContinue && d.heardFromPerson
			valid := msg.ExpectedTurnID == "" || (msg.ExpectedTurnID == d.usageTurnID && active == "" && len(d.queue) == 0)
			model, effort = d.model, d.effort
			d.mu.Unlock()
			if superseded {
				continue
			}
			if !valid {
				d.emit("error", staleLimitResumeError())
				continue
			}
			inputs := a.skillInput(msg.Text)
			d.mu.Lock()
			note := d.adoptionNote
			d.mu.Unlock()
			if note != "" {
				inputs = append([]any{map[string]any{"type": "text", "text": note, "text_elements": []any{}}}, inputs...)
			}
			p := map[string]any{"threadId": thread, "input": inputs}
			if msg.ClientID != "" {
				p["clientUserMessageId"] = msg.ClientID
			}
			method = "turn/start"
			if active != "" {
				method = "turn/steer"
				p["expectedTurnId"] = active
			} else {
				if model != "" {
					p["model"] = model
				}
				if effort != "" {
					p["effort"] = effort
				}
			}
			a.mu.Lock()
			a.starting = active == ""
			a.mu.Unlock()
			result, e := a.call(method, p)
			a.mu.Lock()
			a.starting = false
			a.mu.Unlock()
			if e != nil {
				var rejected codexRPCRejected
				if errors.As(e, &rejected) {
					if rejected.noActiveTurn {
						d.mu.Lock()
						d.retryInput = &msg
						d.mu.Unlock()
						retryDeadline = time.After(5 * time.Second)
						continue
					}
					d.emit("error", agent.ErrorPayload{Message: "Codex did not accept message: " + e.Error(), Retryable: true, ClientID: msg.ClientID})
					continue
				}
				d.emit("error", agent.ErrorPayload{Message: "Codex message delivery could not be confirmed; restarting the runtime to stop unconfirmed work", Retryable: true, ClientID: msg.ClientID})
				return
			}
			d.mu.Lock()
			if note != "" {
				if d.adoptionNote == note {
					d.adoptionNote = ""
				} else if strings.HasPrefix(d.adoptionNote, note) {
					d.adoptionNote = strings.TrimSpace(strings.TrimPrefix(d.adoptionNote, note))
				}
			}
			d.mu.Unlock()
			if active == "" {
				var r struct {
					Turn struct {
						ID string `json:"id"`
					} `json:"turn"`
				}
				_ = json.Unmarshal(result, &r)
				active = r.Turn.ID
				if active == "" {
					d.emit("error", agent.ErrorPayload{Message: "Codex returned no turn identity", Retryable: true, ClientID: msg.ClientID})
					// The RPC succeeded, so acceptance is ambiguous. Stop this runtime
					// before another queued message can start unguarded work.
					return
				}
				turnModel = model
				usage = agent.Usage{}
				usageBase = agent.Usage{}
				usageSeen = false
				d.mu.Lock()
				d.usageTurnID = ccUUID()
				d.activeTurn = true
				d.mu.Unlock()
				d.emit("status_changed", agent.StatusPayload{Status: "running", Reason: "turn"})
			}
			a.mu.Lock()
			a.turn = active
			interrupted := a.interruptRequested
			a.mu.Unlock()
			if interrupted {
				a.interrupt()
			}
			shown := msg.Payload()
			d.mu.Lock()
			shown.TurnID = d.usageTurnID
			d.mu.Unlock()
			d.emit("user_message", shown)
		case <-a.events:
			a.mu.Lock()
			if len(a.backlog) == 0 {
				a.mu.Unlock()
				continue
			}
			ev := a.backlog[0]
			a.backlogBytes -= len(ev.Params)
			a.backlog[0] = codexRPC{}
			a.backlog = a.backlog[1:]
			more := len(a.backlog) > 0
			a.mu.Unlock()
			if more {
				select {
				case a.events <- struct{}{}:
				default:
				}
			}
			if ev.childProof != nil {
				a.acceptChildProof(appCtx, ev.childProof)
				continue
			}
			if ev.questionStatus != nil {
				q := ev.questionStatus
				a.mu.Lock()
				valid := a.turn == q.turn && !a.interruptRequested && ((q.status == "waiting" && a.blockingQuestionCountLocked() > 0) || ((q.status == "running" || q.status == "idle") && a.blockingQuestionCountLocked() == 0))
				a.mu.Unlock()
				if valid {
					reason := "ask"
					if q.status == "running" {
						reason = "ask_answered"
					}
					d.emit("status_changed", agent.StatusPayload{Status: q.status, Reason: reason})
				}
				continue
			}
			if len(ev.ID) > 0 && ev.Method != "" {
				if ev.Method == "account/chatgptAuthTokens/refresh" {
					go a.refreshManagedCredential(appCtx, ev)
					continue
				}
				var origin struct{ ThreadID string }
				if json.Unmarshal(ev.Params, &origin) == nil && origin.ThreadID != "" && origin.ThreadID != thread && a.childNeedsDeferral(origin.ThreadID) {
					a.deferChildEvent(appCtx, origin.ThreadID, ev)
					continue
				}
				if ev.Method == "item/tool/requestUserInput" && !d.codexToolsRestricted() {
					if !a.markQuestionPending(origin.ThreadID, ev.ID) {
						_ = a.writeContext(appCtx, map[string]any{"id": ev.ID, "error": map[string]any{"code": -32602, "message": "User question limit exceeded"}})
						continue
					}
					go a.userQuestions(appCtx, ev)
					continue
				}
				if ev.Method == "item/tool/call" && d.RestrictedRuntime != nil {
					go a.dynamicTool(appCtx, ev)
					continue
				}
				_ = a.writeContext(appCtx, map[string]any{"id": ev.ID, "error": map[string]any{"code": -32601, "message": "Blerg does not support this interactive request"}})
				continue
			}
			var n struct {
				ThreadID  string          `json:"threadId"`
				RequestID json.RawMessage `json:"requestId"`
				Thread    struct {
					ID      string `json:"id"`
					Parent  string `json:"parentThreadId"`
					Model   string `json:"model"`
					Preview string `json:"preview"`
				} `json:"thread"`
				ThreadSettings struct {
					Model  string `json:"model"`
					Effort string `json:"effort"`
				} `json:"threadSettings"`
				ToModel string          `json:"toModel"`
				Delta   string          `json:"delta"`
				Item    json.RawMessage `json:"item"`
				Turn    struct {
					ID     string `json:"id"`
					Status string `json:"status"`
					Error  *struct {
						Message string `json:"message"`
					} `json:"error"`
				} `json:"turn"`
				TokenUsage struct {
					Last  codexTokenUsage  `json:"last"`
					Total *codexTokenUsage `json:"total"`
				} `json:"tokenUsage"`
				Error struct {
					Message string `json:"message"`
				} `json:"error"`
				WillRetry bool `json:"willRetry"`
			}
			if json.Unmarshal(ev.Params, &n) != nil {
				continue
			}
			if ev.Method == "thread/started" && (n.Thread.Parent == thread || d.childKnown(n.Thread.Parent)) {
				// Notification metadata identifies a candidate, never ownership. A
				// foreign thread cannot enroll itself by claiming this root as parent.
				if a.childNeedsDeferral(n.Thread.ID) {
					a.deferChildEvent(appCtx, n.Thread.ID, ev)
					continue
				}
				d.childStatus(n.Thread.ID, n.Thread.Model, n.Thread.Preview, "started")
			}
			parent := ""
			if n.ThreadID != "" && n.ThreadID != thread {
				if a.childNeedsDeferral(n.ThreadID) {
					a.deferChildEvent(appCtx, n.ThreadID, ev)
					continue
				}
				parent = n.ThreadID
			}
			switch ev.Method {
			case "serverRequest/resolved":
				a.resolveQuestionRequest(n.ThreadID, n.RequestID)
			case "turn/started":
				if parent != "" {
					a.startChildTurn(parent, n.Turn.ID)
					d.childStatus(parent, "", "", "running")
				}
			case "thread/settings/updated":
				if parent != "" {
					d.childStatus(parent, n.ThreadSettings.Model, "", "")
					continue
				}
				if n.ThreadSettings.Model != "" {
					d.mu.Lock()
					same := d.model == turnModel || active == ""
					if same {
						d.model = n.ThreadSettings.Model
						if n.ThreadSettings.Effort != "" {
							d.effort = n.ThreadSettings.Effort
						}
					}
					p := agent.ModelChangedPayload{Model: d.model, Effort: d.effort, Source: "start"}
					d.mu.Unlock()
					if same {
						turnModel = n.ThreadSettings.Model
						d.emit("model_changed", p)
					}
				}
			case "model/rerouted":
				if parent == "" && n.ToModel != "" {
					turnModel = n.ToModel
				}
			case "skills/changed", "mcpServer/startupStatus/updated", "mcpServer/oauthLogin/completed":
				if parent == "" && !d.codexToolsRestricted() {
					a.requestCapabilities()
				}
			case "item/started", "item/completed":
				var activity struct{ Type, AgentThreadID string }
				if json.Unmarshal(n.Item, &activity) == nil && activity.Type == "subAgentActivity" && a.childNeedsDeferral(activity.AgentThreadID) {
					a.deferChildEvent(appCtx, activity.AgentThreadID, ev)
					continue
				}
				d.appItem(n.Item, ev.Method == "item/completed", parent)
			case "item/agentMessage/delta":
				d.emit("assistant_text", agent.AssistantTextPayload{Text: n.Delta, ParentCallID: d.childCallID(parent)})
			case "thread/tokenUsage/updated":
				latest := n.TokenUsage.Last.usage()
				if parent != "" {
					if n.TokenUsage.Total != nil {
						latest = n.TokenUsage.Total.usage()
					}
					d.childUsage(parent, latest, n.TokenUsage.Total != nil)
					continue
				}
				if active == "" {
					continue
				}
				if n.TokenUsage.Total != nil {
					total := n.TokenUsage.Total.usage()
					if !usageSeen {
						usageBase = subtractCodexUsage(total, latest)
						usageSeen = true
					}
					usage = subtractCodexUsage(total, usageBase)
				} else {
					usage = latest
				}

			case "error":
				if parent == "" {
					d.appUsageRefusal(n.Error.Message)
				}
				code := agent.ErrorCodeAPI
				if n.WillRetry {
					code = agent.ErrorCodeAPIRetry
				}
				d.emit("error", agent.ErrorPayload{Message: n.Error.Message, Retryable: true, Code: code})
			case "turn/completed":
				if parent != "" {
					a.mu.Lock()
					current := a.childTurns[parent]
					a.mu.Unlock()
					if n.Turn.ID == "" || current != n.Turn.ID {
						continue
					}
				}
				if parent == "" {
					if active == "" || (n.Turn.ID != "" && n.Turn.ID != active) {
						continue
					}
					// Seal registration before cancellation and potentially blocking display
					// delivery. A pending question goroutine either registered already (and
					// is canceled below) or now observes an inactive turn.
					a.mu.Lock()
					a.turn = ""
					a.mu.Unlock()
				}
				a.cancelDynamic(n.ThreadID, n.Turn.ID)
				if parent != "" {
					status := n.Turn.Status
					if status == "failed" {
						status = "errored"
					}
					d.childStatus(parent, "", "", status)
					continue
				}
				if active == "" || (n.Turn.ID != "" && n.Turn.ID != active) {
					continue
				}
				stop := "end_turn"
				if n.Turn.Status == "interrupted" {
					stop = "interrupted"
				}
				if n.Turn.Status == "failed" {
					stop = "error"
					if n.Turn.Error != nil {
						d.appUsageRefusal(n.Turn.Error.Message)
						d.emit("error", agent.ErrorPayload{Message: n.Turn.Error.Message, Retryable: true, Code: agent.ErrorCodeAPI})
					}
				}
				d.emit("turn_done", agent.TurnDonePayload{StopReason: stop, Model: turnModel, Usage: usage})
				active = ""
				a.mu.Lock()
				a.turn = ""
				a.interruptRequested = false
				a.mu.Unlock()
				d.mu.Lock()
				d.activeTurn = false
				d.mu.Unlock()
				a.mu.Lock()
				status := "idle"
				if a.blockingQuestionCountLocked() > 0 {
					status = "waiting"
				}
				a.mu.Unlock()
				d.emit("status_changed", agent.StatusPayload{Status: status, Reason: "turn_done"})
			}
		}
	}
}

// appItem maps only display-safe structured fields. Engine/server credentials
// and MCP connection configuration never enter an event.
func (d *codexDriver) appItem(raw []byte, done bool, parent string) {
	nativeParent := parent
	parent = d.childCallID(parent)
	var i struct {
		Type, ID, Text, Command, AggregatedOutput, Status, Server, Tool, Prompt, Model string
		ContentItems                                                                   []struct{ Type, Text string } `json:"contentItems"`
		Success                                                                        *bool                         `json:"success"`
		ExitCode                                                                       *int
		DurationMs                                                                     int64
		Arguments                                                                      json.RawMessage
		Result                                                                         json.RawMessage
		Error                                                                          json.RawMessage
		Summary                                                                        []string
		Content                                                                        []string
		Changes                                                                        json.RawMessage
		ReceiverThreadIDs                                                              []string
		AgentsStates                                                                   map[string]struct{ Status, Message string }
		AgentThreadID, AgentPath, Kind                                                 string
	}
	if json.Unmarshal(raw, &i) != nil {
		return
	}
	tool := ""
	input := i.Arguments
	output := i.AggregatedOutput
	failed := i.Status == "failed" || (i.ExitCode != nil && *i.ExitCode != 0)
	switch i.Type {
	case "agentMessage":
		if done && i.Text != "" {
			d.emit("assistant_text", agent.AssistantTextPayload{Text: i.Text, Done: true, ParentCallID: parent})
		}
		return
	case "reasoning":
		if done {
			d.emit(agent.KindThinkingDone, agent.ThinkingPayload{ParentCallID: parent})
			text := strings.Join(i.Summary, "\n")
			if text != "" {
				d.emit("assistant_thinking", agent.AssistantThinkingPayload{Text: text, ParentCallID: parent})
			}
		} else {
			d.emit(agent.KindThinkingStarted, agent.ThinkingPayload{ParentCallID: parent})
		}
		return
	case "contextCompaction":
		if done {
			d.emit("compaction", agent.CompactionPayload{Trigger: "auto"})
		}
		return
	case "commandExecution":
		tool = "bash"
		input, _ = json.Marshal(map[string]string{"command": i.Command})
	case "mcpToolCall":
		tool = mcpToolPrefix(i.Server) + i.Tool
		if len(i.Error) > 0 && string(i.Error) != "null" {
			failed = true
			output = string(i.Error)
		} else {
			output = string(i.Result)
		}
	case "fileChange":
		tool = "apply_patch"
		input = i.Changes
		output = string(i.Changes)
	case "dynamicToolCall":
		tool = i.Tool
		parts := []string{}
		for _, c := range i.ContentItems {
			if c.Type == "inputText" {
				parts = append(parts, c.Text)
			}
		}
		output = strings.Join(parts, "\n")
		if i.Success != nil && !*i.Success {
			failed = true
		}
	case "webSearch":
		tool = "web_search"
		input = raw
	case "imageView":
		tool = "view_image"
		input = raw
	case "imageGeneration":
		tool = "image_generation"
		input = raw
	case "collabAgentToolCall":
		tool = i.Tool
		input, _ = json.Marshal(map[string]string{"prompt": i.Prompt})
		if done {
			for id, state := range i.AgentsStates {
				if d.childKnown(id) {
					d.childStatus(id, i.Model, state.Message, state.Status)
				}
			}
		}

	case "subAgentActivity":
		if done {
			if d.childKnown(i.AgentThreadID) {
				d.childStatus(i.AgentThreadID, i.Model, i.AgentPath, i.Kind)
			}
		}
		return
	default:
		return
	}
	if len(input) == 0 || string(input) == "null" {
		input = json.RawMessage(`{}`)
	}
	if done {
		if len(output) > 12000 {
			output = output[:12000] + "…"
		}
		d.emit("tool_result", agent.ToolResultPayload{CallID: i.ID, Output: output, IsError: failed, DurationMs: i.DurationMs, ParentCallID: parent})
	} else {
		if parent != "" {
			d.childTool(nativeParent)
		}
		d.observeTool(tool)
		d.emit("tool_call", agent.ToolCallPayload{Tool: tool, CallID: i.ID, Input: input, ParentCallID: parent})
	}
}

func (d *codexDriver) appUsageRefusal(message string) {
	d.mu.Lock()
	turn := d.usageTurnID
	already := d.lastLimitTurn == turn
	d.mu.Unlock()
	if already {
		return
	}
	if p, ok := codexUsageRefusal(codexEvent{Type: "error", Message: message}, turn); ok && turn != "" {
		d.mu.Lock()
		d.lastLimitTurn = turn
		d.mu.Unlock()
		d.emit("usage_limit", p)
	}
}

func (a *codexApp) threadID() string { a.d.mu.Lock(); defer a.d.mu.Unlock(); return a.d.threadID }

type codexTokenUsage struct {
	Input  int `json:"inputTokens"`
	Cached int `json:"cachedInputTokens"`
	Write  int `json:"cacheWriteInputTokens"`
	Output int `json:"outputTokens"`
}

func (u codexTokenUsage) usage() agent.Usage {
	// Codex inputTokens includes its cached subset. The shared usage contract
	// follows Claude: input, cache reads, and cache writes are disjoint buckets.
	return agent.Usage{InputTokens: max(0, u.Input-u.Cached), OutputTokens: u.Output, CacheReadTokens: u.Cached, CacheWriteTokens: u.Write}
}
func subtractCodexUsage(a, b agent.Usage) agent.Usage {
	return agent.Usage{InputTokens: max(0, a.InputTokens-b.InputTokens), OutputTokens: max(0, a.OutputTokens-b.OutputTokens), CacheReadTokens: max(0, a.CacheReadTokens-b.CacheReadTokens), CacheWriteTokens: max(0, a.CacheWriteTokens-b.CacheWriteTokens)}
}

type codexRPCRejected struct {
	method       string
	noActiveTurn bool
}

func (e codexRPCRejected) Error() string { return "Codex rejected " + e.method }
func (a *codexApp) stop() {
	a.d.mu.Lock()
	cmd := a.d.cmd
	same := a.d.app == a
	a.d.mu.Unlock()
	if same && cmd != nil && cmd.Process != nil {
		_ = cmd.Process.Kill()
	}
}

type codexDynamicCall struct {
	resolved bool
	thread   string
	turn     string
	cancel   context.CancelFunc
}

func (a *codexApp) cancelDynamic(thread, turn string) {
	a.mu.Lock()
	cancels := []context.CancelFunc{}
	for _, call := range a.dynamicCalls {
		if (thread == "" || call.thread == thread) && (turn == "" || call.turn == turn) {
			cancels = append(cancels, call.cancel)
		}
	}
	a.mu.Unlock()
	for _, cancel := range cancels {
		cancel()
	}
}
func (a *codexApp) dynamicTool(ctx context.Context, ev codexRPC) {
	var request struct {
		ThreadID  string          `json:"threadId"`
		TurnID    string          `json:"turnId"`
		Tool      string          `json:"tool"`
		Arguments json.RawMessage `json:"arguments"`
	}
	out := "Tool request is not permitted"
	success := false
	if json.Unmarshal(ev.Params, &request) == nil && request.ThreadID == a.threadID() {
		callCtx, cancel := context.WithCancel(ctx)
		a.mu.Lock()
		valid := request.TurnID == a.turn && !a.interruptRequested
		key := string(ev.ID)
		if valid {
			if a.dynamicCalls == nil {
				a.dynamicCalls = map[string]codexDynamicCall{}
			}
			a.dynamicCalls[key] = codexDynamicCall{thread: request.ThreadID, turn: request.TurnID, cancel: cancel}
		}
		a.mu.Unlock()
		defer func() { cancel(); a.mu.Lock(); delete(a.dynamicCalls, key); a.mu.Unlock() }()
		if valid {
			value, err := a.d.RestrictedRuntime.Call(callCtx, request.Tool, request.Arguments)
			out = value
			success = err == nil
			if err != nil {
				if out != "" {
					out += "\n"
				}
				out += err.Error()
			}
		}
	}
	_ = a.writeContext(ctx, map[string]any{"id": ev.ID, "result": map[string]any{"contentItems": []any{map[string]string{"type": "inputText", "text": out}}, "success": success}})
}

// codexAuthDiagnostic discards raw stderr. Its bounded window recognizes native
// authentication failures even when the process splits a diagnostic across writes.
type codexAuthDiagnostic struct {
	window   string
	reported bool
	emit     func(string, any)
}

func (w *codexAuthDiagnostic) Write(p []byte) (int, error) {
	size := len(p)
	if w.reported {
		return size, nil
	}
	const signature = "auth: Failed to refresh token: Your access token could not be refreshed."
	// Inspect bounded chunks rather than retaining third-party stderr or its secrets.
	for len(p) > 0 {
		n := min(len(p), 256)
		w.window += string(p[:n])
		p = p[n:]
		if strings.Contains(w.window, signature) {
			w.reported = true
			w.window = ""
			w.emit("error", agent.ErrorPayload{Message: "Codex login expired and could not be refreshed. Reconnect your Codex credential in Settings, then retry.", Retryable: true, Code: agent.ErrorCodeAPI})
			break
		}
		if len(w.window) > len(signature) {
			w.window = w.window[len(w.window)-len(signature):]
		}
	}
	return size, nil
}

func (a *codexApp) completionQueued(thread, turn string) bool {
	if turn == "" {
		return false
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	for _, event := range a.backlog {
		if event.Method != "turn/completed" {
			continue
		}
		var p struct {
			ThreadID string
			Turn     struct{ ID string }
		}
		if json.Unmarshal(event.Params, &p) == nil && p.ThreadID == thread && (p.Turn.ID == "" || p.Turn.ID == turn) {
			return true
		}
	}
	return false
}
